(() => {
  const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const request=async(url,body)=>{const response=await fetch(url,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const data=await response.json();if(!response.ok)throw new Error(data.message||'读取失败');return data;};
  async function refresh(){const node=document.querySelector('#connectedModels');if(!node)return;try{const status=await request('/api/status'),providers=status.config.providers||[];node.innerHTML=`<button data-action="connect"><span>已连接模型 <b>${providers.length}</b></span><span>管理 ↗</span></button><p>${providers.length?providers.slice(0,3).map(p=>`<span class="connected-dot"></span>${esc(p.name)}${p.hasKey||p.connected||/^http:\/\/(localhost|127\.0\.0\.1)/.test(p.baseUrl)?'':' · 需连接'}`).join('<br>'):'🔌 添加模型，开始对话与协作'}${providers.length>3?`<br>还有 ${providers.length-3} 个模型`:''}</p>`;}catch{if(node.querySelector('p'))node.querySelector('p').textContent='本地服务暂时未连接';}}
  async function team(draft){
    let panel=document.getElementById('teamDialog');if(panel?.open)return;panel?.remove();panel=document.createElement('dialog');panel.id='teamDialog';panel.className='chat-small-dialog team-dialog';panel.innerHTML='<h2>🤝 你的协作团队</h2><p>你只说要做什么。总控拆解需求、安排成员并整合交付。</p><div id="teamFields">正在读取模型…</div><p role="alert"></p><div class="button-row"><button type="button" class="text-link" data-manage-models>＋ 添加模型</button><button type="button" class="outline-button" data-team-close>关闭</button><button type="button" class="primary-button" data-team-save disabled>保存团队</button></div>';document.body.append(panel);panel.showModal();panel.querySelector('[data-team-close]').onclick=()=>panel.close();panel.querySelector('[data-manage-models]').onclick=async event=>{event.stopPropagation();const draft=Object.fromEntries([...panel.querySelectorAll('[data-team-role]')].map(node=>[node.dataset.teamRole,node.value]));await window.RuntimeUI.openSettings();const connection=document.querySelector('.rt-dialog');connection?.addEventListener('close',()=>{if(panel.open){panel.close();team(draft);}},{once:true});};
    try{const status=await request('/api/status'),providers=status.config.providers||[],mapping=draft||status.config.agentProviders||{};
      const roles=[['orchestrator','🧭 总控','分析目标、派发工作、检查交付'],['frontend','🎨 前端','界面、页面和交互'],['backend','⚙️ 后端','接口、数据和业务逻辑']];
      const field=([id,name,desc])=>`<label class="team-role"><span><strong>${name}</strong><small>${desc}</small></span><select data-team-role="${id}"><option value="">${id==='orchestrator'?'自动使用默认模型':'由总控自动安排'}</option>${providers.map(p=>`<option value="${esc(p.id)}" ${mapping[id]===p.id?'selected':''}>${esc(p.name)} · ${esc(p.model)}</option>`).join('')}</select></label>`;
      panel.querySelector('#teamFields').innerHTML=providers.length?roles.map(field).join('')+`<details class="team-more"><summary>更多角色 · 测试、文档与验收</summary>${[['developer','制作与整合','通用内容与最终文件'],['architect','架构设计','共享接口与目录方案'],['tester','测试','生成检查并反馈问题'],['docs','文档','同步使用说明'],['regression','验收','逐项检查原始需求']].map(field).join('')}</details><p class="team-note">前后端按总控计划参与网站和代码任务；PPT、文档等使用对应制作流程。角色可以来自不同公司，也可以使用同一家公司的不同版本。</p><p class="team-note">Cursor / Claude 订阅尚未提供可执行适配器；接入后才能作为团队成员。</p>`:'<p>先连接至少一个模型，再安排团队。</p><button class="outline-button" data-team-connect>连接模型</button>';
      panel.querySelector('[data-team-connect]')?.addEventListener('click',()=>{panel.close();window.RuntimeUI.openSettings();});const save=panel.querySelector('[data-team-save]');save.disabled=!providers.length;
      save.onclick=async()=>{save.disabled=true;try{const next={...mapping};panel.querySelectorAll('[data-team-role]').forEach(select=>{if(select.value)next[select.dataset.teamRole]=select.value;else delete next[select.dataset.teamRole];});await request('/api/config',{agentProviders:next});panel.close();await window.ChatUI?.refreshModels();await refresh();window.Gongming?.toast('团队已保存，后续任务由总控统一调度');}catch(error){panel.querySelector('[role=alert]').textContent=error.message;}finally{save.disabled=false;}};
    }catch(error){panel.querySelector('[role=alert]').textContent=error.message;}
  }
  document.addEventListener('click',event=>{if(event.target.closest('[data-team-settings]'))team();else if(event.target.closest('[data-manage-models]'))window.RuntimeUI?.openSettings();});
  document.addEventListener('close',()=>refresh(),true);window.addEventListener('focus',refresh);
  window.ConnectionsUI={refresh,team};refresh();
})();
